import { SignalingSessionDO } from "./lib/SignalingSessionDO";
import { isAllowedOrigin } from "./lib/rateLimit";
import { DEFAULT_STUN_SERVERS, parseAndValidateTurnServersJson } from "./lib/iceConfig";
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: generated by opennext at build time
import { default as openNextHandler } from "./.open-next/worker.js";

export { SignalingSessionDO };

const SECURITY_HEADERS: Record<string, string> = {
  "Content-Security-Policy": [
    "default-src 'self'",
    "script-src 'self' 'unsafe-eval' 'unsafe-inline'",
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' blob: data:",
    "font-src 'self' data:",
    "connect-src 'self' wss: https: stun: turn: turns:",
    "media-src 'self' blob:",
    "worker-src 'self' blob:",
    "frame-ancestors 'none'",
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
  ].join("; "),
  "X-Frame-Options": "DENY",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy": "camera=(self), microphone=(), geolocation=(), payment=(), usb=()",
  "Strict-Transport-Security": "max-age=31536000; includeSubDomains; preload",
};

function applySecurityHeaders(res: Response, origin: string | null, isAllowed: boolean): Response {
  const headers = new Headers(res.headers);
  for (const [k, v] of Object.entries(SECURITY_HEADERS)) {
    if (!headers.has(k)) {
      headers.set(k, v);
    }
  }
  if (origin && isAllowed && !headers.has("Access-Control-Allow-Origin")) {
    headers.set("Access-Control-Allow-Origin", origin);
    headers.set("Vary", "Origin");
  }
  return new Response(res.body, {
    status: res.status,
    statusText: res.statusText,
    headers,
  });
}

const worker = {
  async fetch(request: Request, env: Record<string, unknown>, ctx: ExecutionContext) {
    const url = new URL(request.url);
    const origin = request.headers.get("origin");
    const allowed = isAllowedOrigin(origin, url);

    // Block cross-origin requests from untrusted origins on mutating endpoints
    if (origin && !allowed && ["POST", "PATCH", "DELETE", "PUT"].includes(request.method)) {
      return new Response(JSON.stringify({ error: "Forbidden: Untrusted cross-origin request" }), {
        status: 403,
        headers: { "Content-Type": "application/json" },
      });
    }

    // Handle CORS preflight
    if (request.method === "OPTIONS") {
      if (!allowed) {
        return new Response(null, { status: 403 });
      }
      return new Response(null, {
        status: 204,
        headers: {
          "Access-Control-Allow-Origin": origin || "*",
          "Access-Control-Allow-Methods": "GET, POST, PATCH, DELETE, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type, Authorization",
          "Access-Control-Max-Age": "86400",
          Vary: "Origin",
        },
      });
    }

    // Fast-path /api/signal/ice-servers directly from Cloudflare Worker env secrets when TURN_SERVERS_JSON is present and valid
    if (url.pathname === "/api/signal/ice-servers") {
      const turnServersJson = env.TURN_SERVERS_JSON as string | undefined;

      if (turnServersJson) {
        const validated = parseAndValidateTurnServersJson(turnServersJson);
        if (validated) {
          const res = new Response(
            JSON.stringify({
              iceServers: [...DEFAULT_STUN_SERVERS, ...validated.iceServers],
              turnConfigured: validated.turnConfigured,
              source: "worker-turn-secret",
            }),
            {
              headers: {
                "Content-Type": "application/json",
                "Cache-Control": "no-store, no-cache, must-revalidate",
              },
            },
          );
          return applySecurityHeaders(res, origin, allowed);
        }
      }
      // If TURN_SERVERS_JSON is not configured or malformed,
      // fall through to OpenNext handler which evaluates dynamic Cloudflare/Metered APIs or defaults to STUN
    }

    const openNextRes = await openNextHandler.fetch(request, env, ctx);
    return applySecurityHeaders(openNextRes, origin, allowed);
  },
};

export default worker;
